const now = new Date();
const rows = items.flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);

// Schedule precedence (2026-11-13 repair):
// 1. A valid next_run_at governs: due iff it is in the past. An INVALID
//    next_run_at is a data error: never due, flagged for review.
// 2. 'on-demand' agents are never auto-due - even when they have never run.
//    (Pre-repair behavior dispatched ANY never-run agent, including on-demand.)
// 3. Unknown schedules are never auto-due (conservative; logged via flag).
// 4. Never-run agents with a known auto schedule are due once (bootstrap).
// 5. Otherwise age-based on last_run_at per schedule.
const MINUTES = { hourly: 60, daily: 1440, weekly: 10080 };

function due(agent) {
  const out = { ...agent, dispatch_requested_at: now.toISOString() };
  if (agent.next_run_at) {
    const next = new Date(agent.next_run_at);
    if (isNaN(next)) { out.invalid_next_run_at = agent.next_run_at; out._due = false; return out; }
    out._due = next <= now; return out;
  }
  if (!Object.prototype.hasOwnProperty.call(MINUTES, agent.schedule)) {
    out.skipped_schedule = agent.schedule;  // on-demand or unknown: never auto-due
    out._due = false; return out;
  }
  if (!agent.last_run_at) { out._due = true; return out; }  // bootstrap
  const last = new Date(agent.last_run_at);
  if (isNaN(last)) { out.invalid_last_run_at = agent.last_run_at; out._due = false; return out; }
  out._due = (now - last) / 60000 >= MINUTES[agent.schedule];
  return out;
}

return rows.map(due).filter(r => r._due).map(({ _due, ...rest }) => ({ json: rest }));
